/// <summary>
/// Third slice on the Timesheet stream, and the third reader of MonthGate — the closed-month rule is
/// one rule, so book-hours' fold of the MonthClosure stream is reused unchanged rather than copied.
///
/// Both of this slice's rules are enforce="aggregate", so there is no validator: RemoveBooking carries
/// nothing but identifiers, and there is no statement about the request alone left to make. A
/// FluentValidation class with an empty constructor would be a file that asserts nothing.
///
/// The state is fetched with FetchForWriting rather than [Aggregate], because that attribute resolves a
/// stream id from ONE route argument and this stream is keyed by a composite (employeeId + month).
/// </summary>
public static class RemoveBookingEndpoint
{
    /// <summary>
    /// DELETE, and no request body. The two write endpoints before this one POST their command,
    /// because a booking and a correction both carry data the route cannot express. RemoveBooking's
    /// three declared fields — bookingId, employeeId, month — are *exactly* the route, so a body would
    /// be the same facts stated twice, and two places to disagree.
    /// </summary>
    [WolverineDelete("/timesheet/{employeeId}/{month}/bookings/{bookingId}")]
    public static async Task<IResult> Remove(
        Guid employeeId,
        string month,
        Guid bookingId,
        IDocumentSession session,
        CancellationToken cancellation)
    {
        var command = new RemoveBooking(bookingId, employeeId, month);

        // MonthIsClosed. A cross-stream READ of the MonthClosure stream, never a second write: one
        // command, one stream. Writing both would need a transactional boundary around two aggregates,
        // which swimlane/command-crosses-swimlane forbids.
        var gate = await session.Events.FetchLatest<MonthGate>(
            MonthGate.StreamKey(command.EmployeeId, command.Month), cancellation);
        if (gate?.IsClosed == true)
            return Rejections.Problem("MonthIsClosed",
                "A closed month cannot be edited, so a booking in it cannot be removed. Closed is closed.");

        var stream = await session.Events.FetchForWriting<RemoveBookingState>(
            RemoveBookingState.StreamKey(command.EmployeeId, command.Month), cancellation);
        var sheet = stream.Aggregate ?? new RemoveBookingState();

        // BookingNotFound. "A booking already removed cannot be removed again." Removal is therefore
        // deliberately NOT idempotent: the second call is refused rather than quietly answered 204,
        // because a screen showing a row that is no longer there is a stale screen and the user should
        // be told. Same refusal for an id that never existed — the stream cannot tell them apart.
        if (!sheet.IsStanding(command.BookingId))
            return Rejections.Problem("BookingNotFound",
                "There is no standing booking with that id in this month, so there is nothing to remove.");

        stream.AppendOne(new BookingRemoved(
            command.BookingId, command.EmployeeId, command.Month, DateTimeOffset.UtcNow));

        await session.SaveChangesAsync(cancellation);
        return Results.NoContent();
    }
}

